1623	function processGroupRows(pgid: number): ManagedHostRunProcessGroupRow[] | null {
1624	  if (process.platform === 'win32') return null;
1625	  try {
1626	    const output = execFileSync('ps', ['-axo', 'pid=,pgid=,sess=,lstart='], {
1627	      encoding: 'utf8',
1628	      timeout: 1_000,
1629	      stdio: ['ignore', 'pipe', 'ignore'],
1630	    });
1631	    return output
1632	      .split('\n')
1633	      .map(line => /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(.+?)\s*$/.exec(line))
1634	      .filter((match): match is RegExpExecArray => match !== null)
1635	      .map(match => ({ pid: Number(match[1]), pgid: Number(match[2]), sessionId: Number(match[3]), start: match[4]! }))
1636	      .filter(row => row.pgid === pgid);
1637	  } catch {
1638	    return null;
1639	  }
1640	}
