1648	function providerInvocationMatches(
1649	  paths: ManagedHostRunPaths,
1650	  binding: ManagedReviewProposalInvocationBinding,
1651	  callerPid: number,
1652	): boolean {
1653	  if (process.platform === 'win32') return false;
1654	  if (readTerminal(paths)) return false;
1655	  const spec = readJson<ManagedHostRunSpec>(paths.spec);
1656	  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
1657	  if (snapshot.state !== 'running'
1658	    || spec.profile !== 'managed_reviewer'
1659	    || spec.storyId !== binding.storyId
1660	    || spec.agentType !== binding.providerAgent
1661	    || spec.lane !== binding.lane
1662	    || spec.reviewRunId !== binding.reviewRunId) return false;
1663	  const identity = snapshot.providerIdentity;
1664	  if (!identity?.processGroupIsolated || !identity.pgid || !identity.startFingerprint) return false;
1665	  const inspect = (pid: number): { pid: number; pgid: number; sessionId: number; start: string } | null => {
1666	    try {
1667	      const output = execFileSync('ps', ['-o', 'pid=', '-o', 'pgid=', '-o', 'sess=', '-o', 'lstart=', '-p', String(pid)], {
1668	        encoding: 'utf8', timeout: 1_000, stdio: ['ignore', 'pipe', 'ignore'],
1669	      }).trim();
1670	      const match = /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(.+?)\s*$/.exec(output);
1671	      return match
1672	        ? { pid: Number(match[1]), pgid: Number(match[2]), sessionId: Number(match[3]), start: match[4]! }
1673	        : null;
1674	    } catch { return null; }
1675	  };
1676	  const leader = inspect(identity.pid);
1677	  const caller = inspect(callerPid);
1678	  return leader !== undefined
1679	    && leader !== null
1680	    && caller !== null
1681	    && leader.pgid === identity.pgid
1682	    && caller.pgid === identity.pgid
1683	    && leader.start === identity.startFingerprint
1684	    && leader.sessionId === caller.sessionId;
1685	}
