1687	/**
1688	 * Provider-tool broker: resolve exactly one active managed reviewer whose
1689	 * recorded provider process group contains this invocation. PGID is never a
1690	 * bearer by itself: exact review binding, live leader fingerprint, POSIX
1691	 * session, non-terminal state, and unique candidate are all mandatory.
1692	 */
1693	export function resolveManagedReviewProposalInvocation(args: {
1694	  root: string;
1695	  binding: ManagedReviewProposalInvocationBinding;
1696	  callerPid?: number;
1697	}): string {
1698	  if (process.platform === 'win32') {
1699	    throw new Error('managed_review_proposal_set: provider invocation broker is unsupported on win32');
1700	  }
1701	  const callerPid = args.callerPid ?? process.pid;
1702	  const candidates: string[] = [];
1703	  let entries: string[] = [];
1704	  try { entries = readdirSync(managedHostRunsRoot(args.root)); } catch { /* no active managed runs */ }
1705	  for (const runId of entries) {
1706	    try {
1707	      const paths = pathsFor(args.root, runId);
1708	      if (providerInvocationMatches(paths, args.binding, callerPid)) candidates.push(runId);
1709	    } catch {
1710	      // Corrupt/partial candidates cannot grant provider authority.
1711	    }
1712	  }
1713	  if (candidates.length !== 1) {
1714	    throw new Error(
1715	      `managed_review_proposal_set: provider invocation must match exactly one active managed reviewer (matched ${candidates.length})`,
1716	    );
1717	  }
1718	  return candidates[0]!;
1719	}
