1721	export function readManagedReviewProposalInvocationFromFd(
1722	  env: NodeJS.ProcessEnv = process.env,
1723	): ManagedReviewProposalInvocationAttestation | null {
1724	  const rawFd = env.LATTICE_MANAGED_REVIEW_INVOCATION_FD?.trim();
1725	  if (!rawFd) return null;
1726	  const fd = Number(rawFd);
1727	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
1728	    throw new Error('managed_review_proposal_set: invocation fd must be between 3 and 255');
1729	  }
1730	  const raw = readFileSync(fd, 'utf8');
1731	  if (Buffer.byteLength(raw, 'utf8') > 64 * 1024) {
1732	    throw new Error('managed_review_proposal_set: invocation attestation exceeds 64 KiB');
1733	  }
1734	  try {
1735	    return JSON.parse(raw) as ManagedReviewProposalInvocationAttestation;
1736	  } catch {
1737	    throw new Error('managed_review_proposal_set: invocation fd does not contain JSON');
1738	  }
