1741	function verifyManagedReviewProposalInvocationAttestation(
1742	  paths: ManagedHostRunPaths,
1743	  binding: ManagedReviewProposalInvocationBinding,
1744	  attestation: ManagedReviewProposalInvocationAttestation,
1745	): boolean {
1746	  if (readTerminal(paths)) return false;
1747	  const spec = readJson<ManagedHostRunSpec>(paths.spec);
1748	  const owner = readJson<ManagedHostRunOwner>(paths.owner);
1749	  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
1750	  if (!owner.proposalInvocationPublicKey || snapshot.state !== 'running' || !snapshot.providerIdentity) return false;
1751	  const { signature, ...claims } = attestation;
1752	  const issuedAt = Date.parse(attestation.issuedAt);
1753	  const expiresAt = Date.parse(attestation.expiresAt);
1754	  const now = Date.now();
1755	  return attestation.schemaVersion === 'lattice.managed_review_proposal_invocation.v1'
1756	    && attestation.runId === spec.runId
1757	    && attestation.storyId === binding.storyId
1758	    && attestation.providerAgent === binding.providerAgent
1759	    && attestation.lane === binding.lane
1760	    && attestation.reviewRunId === binding.reviewRunId
1761	    && spec.profile === 'managed_reviewer'
1762	    && spec.storyId === binding.storyId
1763	    && spec.agentType === binding.providerAgent
1764	    && spec.lane === binding.lane
1765	    && spec.reviewRunId === binding.reviewRunId
1766	    && canonicalJson(attestation.providerIdentity) === canonicalJson(snapshot.providerIdentity)
1767	    && snapshot.providerIdentity.processGroupIsolated
1768	    && snapshot.providerIdentity.pgid !== null
1769	    && snapshot.providerIdentity.startFingerprint !== null
1770	    && /^[A-Za-z0-9._-]{16,128}$/.test(attestation.invocationNonce)
1771	    && Number.isFinite(issuedAt)
1772	    && Number.isFinite(expiresAt)
1773	    && issuedAt <= now + 5_000
1774	    && expiresAt >= now
1775	    && expiresAt > issuedAt
1776	    && expiresAt - issuedAt <= 120_000
1777	    && verifyCanonical(claims, signature, owner.proposalInvocationPublicKey);
1778	}
