1798	export async function reapManagedHostRunProviderProcess(
1799	  identity: HostRunProcessIdentity | null,
1800	  ops: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
1801	): Promise<HostRunProcessCleanup> {
1802	  if (!identity?.processGroupIsolated || !identity.pgid || !identity.startFingerprint) {
1803	    return AMBIGUOUS_PROCESS_CLEANUP;
1804	  }
1805	  let rows = ops.rows(identity.pgid);
1806	  if (rows === null) return AMBIGUOUS_PROCESS_CLEANUP;
1807	  if (rows.length === 0) return REAPED_WITHOUT_SIGNAL;
1808	  const leader = rows.find(row => row.pid === identity.pid);
1809	  if (!leader || leader.start !== identity.startFingerprint) return AMBIGUOUS_PROCESS_CLEANUP;
1810	
1811	  let termSent = false;
1812	  try {
1813	    ops.signal(identity.pgid, 'SIGTERM');
1814	    termSent = true;
1815	  } catch (error) {
1816	    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') return AMBIGUOUS_PROCESS_CLEANUP;
1817	  }
1818	  await ops.wait(250);
1819	  rows = ops.rows(identity.pgid);
1820	  if (rows === null) return { termSent, killSent: false, reaped: false, residualProcessGroup: true };
1821	  if (rows.length === 0) return { termSent, killSent: false, reaped: true, residualProcessGroup: false };
1822	  const postTermLeader = rows.find(row => row.pid === identity.pid);
1823	  if (!postTermLeader || postTermLeader.start !== identity.startFingerprint) {
1824	    return { termSent, killSent: false, reaped: false, residualProcessGroup: true };
1825	  }
1826	  let killSent = false;
1827	  try {
1828	    ops.signal(identity.pgid, 'SIGKILL');
1829	    killSent = true;
1830	  } catch (error) {
1831	    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') {
1832	      return { termSent, killSent, reaped: false, residualProcessGroup: true };
1833	    }
1834	  }
1835	  await ops.wait(250);
1836	  rows = ops.rows(identity.pgid);
1837	  const reaped = rows !== null && rows.length === 0;
1838	  return { termSent, killSent, reaped, residualProcessGroup: !reaped };
1839	}
