1841	async function reconcileManagedHostRunUnlocked(
1842	  paths: ManagedHostRunPaths,
1843	  now: number,
1844	  processGroupOps: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
1845	): Promise<void> {
1846	  if (readTerminal(paths)) return;
1847	  const spec = readJson<ManagedHostRunSpec>(paths.spec);
1848	  const fenceLaunchBeforeTerminal = (): 'revoked' | 'granted' | 'spawned' => withTerminalAuthorityLock(paths, () => {
1849	    const current = readJson<ManagedHostRunSnapshot>(paths.snapshot);
1850	    const state = current.providerLaunchState
1851	      ?? (current.providerIdentity ? 'spawned' : current.state === 'submitted' ? 'pending' : 'granted');
1852	    if (state === 'pending' || state === 'revoked') {
1853	      if (state === 'pending') {
1854	        updateSnapshotUnlocked(paths, value => ({ ...value, providerLaunchState: 'revoked' }));
1855	      }
1856	      return 'revoked';
1857	    }
1858	    return state;
1859	  });
1860	  if (now >= Date.parse(spec.deadlineAt)) {
1861	    const request = ensureCancelRequest(paths, spec.runId, 'absolute_deadline_exceeded', now);
1862	    // Give a healthy worker a short cooperative window. A genuinely wedged
1863	    // worker cannot hold the status API forever: after the grace, the next touch
1864	    // reconciles against the recorded provider identity and writes an honest
1865	    // terminal even when replacement safety cannot be proven.
1866	    if (now - Date.parse(request.requestedAt) < 250) return;
1867	    const launchState = fenceLaunchBeforeTerminal();
1868	    const fencedSnapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
1869	    const cleanup = launchState === 'revoked'
1870	      ? REAPED_WITHOUT_SIGNAL
1871	      : fencedSnapshot.providerIdentity
1872	        ? await reapManagedHostRunProviderProcess(fencedSnapshot.providerIdentity, processGroupOps)
1873	        : AMBIGUOUS_PROCESS_CLEANUP;
1874	    writeTerminal(
1875	      paths,
1876	      'timed_out',
1877	      'absolute_deadline_exceeded',
1878	      cleanupIsReplacementSafe(cleanup),
1879	      null,
1880	      now,
1881	      cleanup,
1882	    );
1883	    return;
1884	  }
1885	  const cancel = readCancelRequest(paths);
1886	  if (cancel && now - Date.parse(cancel.requestedAt) >= 250) {
1887	    const launchState = fenceLaunchBeforeTerminal();
1888	    const fencedSnapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
1889	    if (launchState === 'granted'
1890	      && fencedSnapshot.providerIdentity === null
1891	      && fencedSnapshot.workerPid !== null
1892	      && pidAlive(fencedSnapshot.workerPid)) return;
1893	    const cleanup = launchState === 'revoked'
1894	      ? REAPED_WITHOUT_SIGNAL
1895	      : fencedSnapshot.providerIdentity
1896	        ? await reapManagedHostRunProviderProcess(fencedSnapshot.providerIdentity, processGroupOps)
1897	        : AMBIGUOUS_PROCESS_CLEANUP;
1898	    const terminal = classifyManagedHostRunCancellation(cancel.reason);
1899	    writeTerminal(
1900	      paths,
1901	      terminal.state,
1902	      terminal.reason,
1903	      cleanupIsReplacementSafe(cleanup),
1904	      null,
1905	      now,
1906	      cleanup,
1907	    );
1908	  }
1909	}
