1921	export async function getManagedHostRunStatus(args: {
1922	  root: string;
1923	  runId: string;
1924	  afterGeneration?: number;
1925	  waitMs?: number;
1926	  /** Internal handler-smoke seam; production omits this and retains the 30s cap. */
1927	  maxWaitMs?: number;
1928	  /** Internal process-smoke clock seam; production always uses Date.now. */
1929	  now?: () => number;
1930	  /** Process-boundary seam used by executable cleanup-fact tests; production uses OS process groups. */
1931	  processGroupOps?: ManagedHostRunProcessGroupOps;
1932	}): Promise<ManagedHostRunStatusResult> {
1933	  const paths = pathsFor(args.root, args.runId);
1934	  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
1935	  const waitMs = Math.min(
1936	    boundedManagedHostRunStatusWaitMs(args.waitMs),
1937	    boundedManagedHostRunStatusWaitMs(args.maxWaitMs ?? MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS),
1938	  );
1939	  let run = projectionFor(paths);
1940	  const baseline = typeof args.afterGeneration === 'number' ? args.afterGeneration : run.generation;
1941	  const now = args.now ?? Date.now;
1942	  const deadline = now() + waitMs;
1943	  while (true) {
1944	    await reconcileManagedHostRun(paths, now(), args.processGroupOps);
1945	    run = projectionFor(paths);
1946	    const changed = run.generation !== baseline || run.terminal !== null;
1947	    if (changed || now() >= deadline || waitMs === 0) {
1948	      return {
1949	        schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
1950	        changed,
1951	        run,
1952	        receipt: run.terminal ? managedHostRunReceipt(args.root, args.runId) : null,
1953	      };
1954	    }
1955	    await sleep(Math.min(50, Math.max(1, deadline - now())));
1956	  }
1957	}
