193	export function writeProviderProcessSlotExclusive(
194	  file: string,
195	  meta: ProviderProcessSlotFileMeta,
196	): boolean {
197	  try {
198	    writeFileSync(file, JSON.stringify(meta), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
