206	function scanLiveProviderProcessSlotsUnlocked(
207	  dir: string,
208	  now: number,
209	  staleMs: number,
210	): ProviderProcessLiveDescriptor[] {
211	  let entries: string[];
212	  try {
213	    entries = readdirSync(dir);
214	  } catch {
215	    return [];
216	  }
217	  const live: ProviderProcessLiveDescriptor[] = [];
218	  for (const name of entries) {
219	    if (!name.endsWith('.json')) continue;
220	    const file = join(dir, name);
221	    const occupant = readSlotOccupant(file);
222	    if (slotReclaimable(occupant, file, now, staleMs)) {
223	      if (occupant.state !== 'missing' && sameSlotOccupant(readSlotOccupant(file), occupant)) {
224	        try { unlinkSync(file); } catch { /* racing reclaim is benign */ }
225	      }
226	      continue;
227	    }
228	    if (occupant.state !== 'valid') continue;
229	    live.push({
230	      pid: occupant.pid,
231	      startedAt: ownString(occupant.meta, 'startedAt') ?? '',
232	      host: ownString(occupant.meta, 'host') ?? '',
233	      storyId: ownString(occupant.meta, 'storyId'),
234	      agentType: ownString(occupant.meta, 'agentType') ?? '',
235	    });
236	  }
